import numpy as np
import os, sys
sys.path.append('storage/verity')
import scp_lp_core as core

N = 32

def _directions():
    # 8 directions: axial and diagonals (normalized)
    dirs = [
        np.array([1.0, 0.0]), np.array([-1.0, 0.0]),
        np.array([0.0, 1.0]), np.array([0.0, -1.0]),
        np.array([1.0, 1.0]), np.array([-1.0, 1.0]),
        np.array([1.0, -1.0]), np.array([-1.0, -1.0]),
    ]
    for i in range(4, 8):
        dirs[i] /= np.linalg.norm(dirs[i])
    return dirs

def _score(C):
    r, ok = core.solve_radii_lp_zero_slack(C)
    return float(np.sum(r)), r, ok

def micro_grid_refine(C_start, passes=3, step_list=(6e-4, 3e-4, 1.5e-4), improve_tol=1e-10):
    C_best = C_start.copy()
    s_best, r_best, ok = _score(C_best)
    if not ok:
        return C_best, r_best, s_best
    dirs = _directions()
    for p in range(passes):
        improved_any = False
        for i in range(N):
            # Greedy per-circle improvement
            improved_i = True
            while improved_i:
                improved_i = False
                for d in dirs:
                    for step in step_list:
                        C_try = C_best.copy()
                        C_try[i] = np.clip(C_try[i] + step * d, 0.0, 1.0)
                        s_try, r_try, ok2 = _score(C_try)
                        if ok2 and s_try > s_best + improve_tol:
                            C_best, r_best, s_best = C_try, r_try, s_try
                            improved_any = True
                            improved_i = True
                            break
                    if improved_i:
                        break
        if not improved_any:
            break
    # Finalize safety (idempotent if already exact)
    r_best = core.finalize_minimal(C_best, r_best, neg_tol=1e-12)
    return C_best, r_best, s_best

def _fallback_grid():
    xs = np.linspace(0.1, 0.9, 6)
    ys = np.linspace(0.1, 0.9, 6)
    centers = []
    for ix, x in enumerate(xs):
        for iy, y in enumerate(ys):
            if (ix in (0, 5)) and (iy in (0, 5)):
                continue
            centers.append([x, y])
    return np.array(centers, dtype=float)

def construct_packing() -> tuple:
    seeds = []
    C0 = core.seed_storage_best()
    if C0 is not None:
        seeds.append(("storage-best", C0))
        Cj = core.seed_storage_best_jitter(amplitude=0.001, seed=7003)
        if Cj is not None:
            seeds.append(("storage-best-jitter-0.001", Cj))
    else:
        seeds.append(("grid-36minus4", _fallback_grid()))

    best_sum = -1.0; best_C = None; best_r = None
    for name, C in seeds:
        C = np.clip(C, 0.0, 1.0)
        print(f"[seed] {name}")
        # Optional quick SCP-LP polish before micro-grid (keeps determinism)
        C_opt, r_opt, s_opt = core.candidate_optimize(C, max_outer=80, min_tau=5e-4, verbose=False)
        print(f"[seed] {name} -> SCP-LP {s_opt:.9f}")
        C_ref, r_ref, s_ref = micro_grid_refine(C_opt, passes=3, step_list=(6e-4,3e-4,1.5e-4), improve_tol=1e-10)
        print(f"[seed] {name} -> micro-grid {s_ref:.9f}")
        if s_ref > best_sum:
            best_sum, best_C, best_r = s_ref, C_ref, r_ref

    # Persist and return
    try:
        os.makedirs("storage/verity", exist_ok=True)
        np.save("storage/verity/best_centers.npy", best_C)
        np.save("storage/verity/best_radii.npy", best_r)
    except Exception:
        pass
    return np.array(best_C, dtype=float), np.array(best_r, dtype=float)
